export async function countIssues(
  orgId: OrgId,
  projectId: ProjectId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const sequence = getDb().select({ value: projectIssueSequences.lastNumber })
    .from(projectIssueSequences)
    .where(and(eq(projectIssueSequences.orgId, orgId), eq(projectIssueSequences.projectId, projectId)))
    .get();
  return Math.max(row?.value ?? 0, sequence?.value ?? 0) + 1;
}

export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const row = db
    .insert(issues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      number: issueNumber,
      title: input.title,
      description: input.description,
      status: input.status,
      priority: input.priority,
      authorId,
      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  db.insert(projectIssueSequences).values({ orgId: input.orgId, projectId: input.projectId, lastNumber: issueNumber })
    .onConflictDoUpdate({
      target: [projectIssueSequences.orgId, projectIssueSequences.projectId],
      set: { lastNumber: sql`max(${projectIssueSequences.lastNumber}, ${issueNumber})` },
    }).run();

  if (input.labelIds.length > 0) {
    db.insert(issueLabels)
      .values(
        input.labelIds.map((labelId) => ({
          orgId: input.orgId,
          issueId: row.id,
          labelId,
        })),
      )
      .run();
  }

  return toIssue(row, input.labelIds);
}

export async function purgeArchivedIssue(orgId: OrgId, issueId: IssueId): Promise<{ storageMb: number; commentIds: readonly string[] }> {
  const db = getDb();
  const attachmentsRows = db.select({ sizeBytes: attachments.sizeBytes }).from(attachments)
    .where(and(orgPredicate(attachments.orgId, orgId), eq(attachments.issueId, issueId))).all();
  const commentRows = db.select({ id: comments.id }).from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId))).all();
  db.delete(searchIndex).where(and(orgPredicate(searchIndex.orgId, orgId), eq(searchIndex.subjectKind, "issue"), eq(searchIndex.subjectId, issueId))).run();
  if (commentRows.length) db.delete(searchIndex).where(and(orgPredicate(searchIndex.orgId, orgId), eq(searchIndex.subjectKind, "comment"), inArray(searchIndex.subjectId, commentRows.map((r) => r.id)))).run();
  db.delete(issueLabels).where(and(orgPredicate(issueLabels.orgId, orgId), eq(issueLabels.issueId, issueId))).run();
  db.delete(comments).where(and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId))).run();
  db.delete(attachments).where(and(orgPredicate(attachments.orgId, orgId), eq(attachments.issueId, issueId))).run();
  db.delete(issues).where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId), isNotNull(issues.archivedAt))).run();
  return { storageMb: attachmentsRows.reduce((sum, row) => sum + Math.ceil(row.sizeBytes / (1024 * 1024)), 0), commentIds: commentRows.map((row) => row.id) };
}

